import json
import urllib.request

# URL pattern for retrieving data - using the one that worked before
indicators = ['NGDPD', 'RGDPD', 'RGDP_RPCH']
country = 'GEO'

for indicator in indicators:
    url = f"https://www.imf.org/external/datamapper/api/v1/data/indicator/{indicator}/country/{country}"
    try:
        with urllib.request.urlopen(url) as response:
            data = json.loads(response.read().decode())
            print(f"\n=== {indicator} ===")
            if 'values' in data and indicator in data['values']:
                values = data['values'][indicator]
                if country in values:
                    for year in sorted(values[country].keys(), key=int):
                        year_int = int(year)
                        if 2000 <= year_int <= 2027:
                            print(f"{year}: {values[country][year]}")
            else:
                print(f"No data found in expected format")
    except Exception as e:
        print(f"Error retrieving {indicator}: {str(e)}")

