python3 << 'EOF'
import json
import urllib.request

indicators = {
    'NGDPD': 'Nominal GDP (USD billions)',
    'NGDP_RPCH': 'Nominal GDP Growth Rate (%)'
}
country = 'GEO'

all_data = {}

for indicator, label in indicators.items():
    url = f"https://www.imf.org/external/datamapper/api/v1/data/indicator/{indicator}/country/{country}"
    try:
        with urllib.request.urlopen(url) as response:
            data = json.loads(response.read().decode())
            if 'values' in data and indicator in data['values']:
                values = data['values'][indicator]
                if country in values:
                    all_data[indicator] = values[country]
    except Exception as e:
        print(f"Error: {e}")

# Create structured output
years = range(2000, 2028)
print("Georgia Economic Data (2000-2027)")
print("=" * 80)
print(f"{'Year':<8} {'Nominal GDP (USD Bil)':<25} {'Nominal GDP Growth (%)':<25}")
print("-" * 80)

for year in years:
    year_str = str(year)
    ngdpd = all_data.get('NGDPD', {}).get(year_str, 'N/A')
    growth = all_data.get('NGDP_RPCH', {}).get(year_str, 'N/A')

    if isinstance(ngdpd, (int, float)):
        ngdpd = f"{ngdpd:.2f}"
    if isinstance(growth, (int, float)):
        growth = f"{growth:.2f}"

    print(f"{year:<8} {ngdpd:<25} {growth:<25}")

EOF

